package main
import("testing";"encoding/json";"reflect")
func TestPublic(t *testing.T){var inputs []map[string]any;_ = json.Unmarshal([]byte(`[{"layers": []}, {"layers": [{"a": 1}]}]`),&inputs);var expected []any;_ = json.Unmarshal([]byte(`[{}, {"a": 1}]`),&expected);for i,x:=range inputs{b,_:=json.Marshal(solve(x));var actual any;_ = json.Unmarshal(b,&actual);if !reflect.DeepEqual(actual,expected[i]){t.Fatalf("case %d: got %v want %v",i,actual,expected[i])}}}

